    /** True when the key is in the text as a whole word (or word start for long words); Hindi keys match anywhere. */
    internal fun hit(t: String, k: String): Boolean {
        if (k.any { it.code > 127 }) return t.contains(k)
        var i = t.indexOf(k)
        while (i >= 0) {
            val before = i == 0 || !t[i - 1].isLetterOrDigit()
            val end = i + k.length
            val after = end >= t.length || !t[end].isLetterOrDigit()
            if (before && (after || k.length >= 5)) return true
            i = t.indexOf(k, i + 1)
        }
        return false
    }

    /** Best 2 matching device procedures plus the rules, or "" when the task has nothing to do with phone settings or chips. */
    private val GATE = listOf("setting", "settings", "सेटिंग", "phone", "फोन", "mobile", "मोबाइल", "android", "iphone", "ios", "processor", "प्रोसेसर", "chip", "snapdragon", "dimensity", "tensor",
        "battery", "बैटरी", "wifi", "wi-fi", "bluetooth", "hotspot", "storage", "स्टोरेज", "update", "अपडेट", "reset", "brightness", "volume", "display", "airplane", "developer", "permission", "how to use", "kaise", "samsung", "xiaomi", "pixel")

    fun forTask(job: String, pkg: String): String {
        val t = job.lowercase()
        if (!pkg.contains("settings") && GATE.none { hit(t, it) }) return ""
        val best = FLOWS.map { (keys, text) -> keys.count { hit(t, it) } to text }
            .filter { it.first > 0 }
            .sortedByDescending { it.first }
            .take(2)
        if (best.isEmpty()) return ""
        val sb = StringBuilder()
        sb.append(RULES).append('\n')
        sb.append(DeviceProfile.forTask(t)).append('\n')
        for ((_, text) in best) sb.append(text).append('\n')
        if (t.contains("latest") || t.contains("newest") || t.contains("current") || t.contains("version") || t.contains("best")) sb.append(LATEST).append('\n')
        return sb.toString().take(7000)
    }

    /** Everything as plain text, for a settings or help screen. */
    fun all(): String = RULES + "\n" + LATEST + "\n" + FLOWS.joinToString("\n") { it.second }
}
